const node_fs_engine = require('node:fs');
const node_path_engine = require('node:path');

function getAllEngineDirs() {
  const dirs = [
    getLocalEnginesDir(),
    node_path_engine.resolve(__dirname, '../../../..', '.runtime', 'desktop', 'resources', 'backend', '_internal', 'app', 'resources', 'channel_engines'),
    node_path_engine.resolve(__dirname, '../../../..', 'recovered', 'backend', 'shipped', 'app', 'resources', 'channel_engines'),
    node_path_engine.resolve(__dirname, '../../../..', 'dist-release', 'Viteraz-Studio-v1.4.3', 'resources', 'backend', '_internal', 'app', 'resources', 'channel_engines'),
    node_path_engine.resolve(__dirname, '../../..', 'backend', '_internal', 'app', 'resources', 'channel_engines')
  ];
  return [...new Set(dirs.filter(d => d && node_fs_engine.existsSync(d)))];
}

function getLocalEnginesDir() {
  const candidates = [
    node_path_engine.resolve(__dirname, '../../..', 'backend', '_internal', 'app', 'resources', 'channel_engines'),
    node_path_engine.resolve(__dirname, '../../../..', '.runtime', 'desktop', 'resources', 'backend', '_internal', 'app', 'resources', 'channel_engines'),
    node_path_engine.resolve(__dirname, '../../../..', 'recovered', 'backend', 'shipped', 'app', 'resources', 'channel_engines'),
  ];
  for (const c of candidates) {
    if (node_fs_engine.existsSync(c)) return c;
  }
  return null;
}

function getNextOrder(dir) {
  let maxOrder = 32;
  const files = node_fs_engine.readdirSync(dir);
  for (const f of files) {
    const m = f.match(/^(\d{2})-.+\.md$/);
    if (m) {
      const num = parseInt(m[1], 10);
      if (num > maxOrder && num < 99) maxOrder = num;
    }
  }
  return String(maxOrder + 1).padStart(2, '0');
}

function findEngineFile(dir, id) {
  const files = node_fs_engine.readdirSync(dir);
  for (const f of files) {
    if (!f.endsWith('.md')) continue;
    if (f.endsWith('-' + id + '.md') || f === (id + '.md')) {
      return node_path_engine.join(dir, f);
    }
    try {
      const c = node_fs_engine.readFileSync(node_path_engine.join(dir, f), 'utf8');
      if (c.includes('id: ' + id) || c.includes('id: "' + id + '"')) {
        return node_path_engine.join(dir, f);
      }
    } catch {}
  }
  return null;
}

async function reloadBackendEngines() {
  if (sidecar && sidecar.baseUrl && sidecar.token) {
    try {
      await fetch(sidecar.baseUrl + '/api/v1/ai-studio/engines/reload', {
        method: 'POST',
        headers: { 'X-Studio-Token': sidecar.token }
      });
    } catch {}
  }
}

function slugifyEngine(name) {
  if (!name) return 'niche';
  return name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'niche';
}

function engineToMarkdown(data, id) {
  const meta = Object.assign({}, data.meta || {});
  if (data.niche) meta.niche = data.niche;
  if (data.language) meta.language = data.language;
  if (data.aspect_ratio || data.aspectRatio) meta.aspect_ratio = data.aspect_ratio || data.aspectRatio;
  if (data.visual_style || data.visualStyle) meta.visual_style = data.visual_style || data.visualStyle;
  if (data.style_anchor || data.styleAnchor) meta.style_anchor = data.style_anchor || data.styleAnchor;
  if (data.style_lock || data.styleLock) meta.style_lock = data.style_lock || data.styleLock;
  if (data.tts_mood) meta.tts_mood = data.tts_mood;
  if (data.music_mood) meta.music_mood = data.music_mood;
  if (data.narration_tone) meta.narration_tone = data.narration_tone;
  if (data.narration_pov) meta.narration_pov = data.narration_pov;
  if (data.video_length) meta.video_length = data.video_length;
  if (data.recurring_character) meta.recurring_character = data.recurring_character;

  const lines = ['---'];
  lines.push('id: ' + id);
  lines.push('name: "' + (data.name || meta.name || id).replace(/"/g, '\\"') + '"');
  lines.push('niche: "' + (meta.niche || '').replace(/"/g, '\\"') + '"');
  lines.push('language: ' + (meta.language || 'vi'));
  lines.push('aspect_ratio: "' + (meta.aspect_ratio || '16:9') + '"');
  lines.push('visual_style: "' + (meta.visual_style || '').replace(/"/g, '\\"') + '"');
  lines.push('style_anchor: "' + (meta.style_anchor || '').replace(/"/g, '\\"') + '"');
  lines.push('style_lock: "' + (meta.style_lock || '').replace(/"/g, '\\"') + '"');
  if (meta.tts_mood) lines.push('tts_mood: "' + String(meta.tts_mood).replace(/"/g, '\\"') + '"');
  if (meta.music_mood) lines.push('music_mood: "' + String(meta.music_mood).replace(/"/g, '\\"') + '"');
  if (meta.narration_tone) lines.push('narration_tone: "' + String(meta.narration_tone).replace(/"/g, '\\"') + '"');
  if (meta.narration_pov) lines.push('narration_pov: "' + String(meta.narration_pov).replace(/"/g, '\\"') + '"');
  if (meta.video_length) lines.push('video_length: "' + String(meta.video_length).replace(/"/g, '\\"') + '"');
  if (meta.recurring_character) lines.push('recurring_character: "' + String(meta.recurring_character).replace(/"/g, '\\"') + '"');
  lines.push('tags: [custom, user]');
  lines.push('---');
  lines.push('');
  lines.push(data.body || meta.body || '<!-- Custom engine -->');
  return lines.join('\n');
}

async function createEngine(data) {
  try {
    const dirs = getAllEngineDirs();
    const id = data.id || data.code || ('custom-' + slugifyEngine(data.name || 'style') + '-' + Date.now().toString(36));
    const mainDir = getLocalEnginesDir();
    const order = mainDir ? getNextOrder(mainDir) : '33';
    const filename = order + '-' + id + '.md';
    const content = engineToMarkdown(data, id);
    for (const d of dirs) {
      try {
        node_fs_engine.writeFileSync(node_path_engine.join(d, filename), content, 'utf8');
      } catch {}
    }
    await reloadBackendEngines();
    return { ok: true, code: id };
  } catch (err) {
    return { ok: false, error: err.message || 'CREATE_ENGINE_FAILED' };
  }
}

async function updateEngine(id, data) {
  try {
    const dirs = getAllEngineDirs();
    const mainDir = getLocalEnginesDir();
    let existingBody = '';
    let targetFilename = null;
    if (mainDir) {
      const targetFile = findEngineFile(mainDir, id);
      if (targetFile && node_fs_engine.existsSync(targetFile)) {
        targetFilename = node_path_engine.basename(targetFile);
        try {
          const raw = node_fs_engine.readFileSync(targetFile, 'utf8');
          const m = raw.match(/^---\r?\n[\s\S]*?\r?\n---\r?\n([\s\S]*)$/);
          if (m && m[1]) existingBody = m[1].trim();
        } catch {}
      }
    }
    if (!targetFilename) {
      const order = mainDir ? getNextOrder(mainDir) : '33';
      targetFilename = order + '-' + id + '.md';
    }
    if (!data.body && existingBody) {
      data.body = existingBody;
    }
    const content = engineToMarkdown(data, id);
    for (const d of dirs) {
      try {
        const found = findEngineFile(d, id);
        const dest = found || node_path_engine.join(d, targetFilename);
        node_fs_engine.writeFileSync(dest, content, 'utf8');
      } catch {}
    }
    await reloadBackendEngines();
    return { ok: true, code: id };
  } catch (err) {
    return { ok: false, error: err.message || 'UPDATE_ENGINE_FAILED' };
  }
}
