async function deleteEngine(id) {
  try {
    const dirs = getAllEngineDirs();
    for (const d of dirs) {
      try {
        const target = findEngineFile(d, id);
        if (target && node_fs_engine.existsSync(target)) {
          node_fs_engine.unlinkSync(target);
        }
      } catch {}
    }
    await reloadBackendEngines();
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err.message || 'DELETE_ENGINE_FAILED' };
  }
}

async function cloneEngine(id) {
  try {
    const dirs = getAllEngineDirs();
    const mainDir = getLocalEnginesDir();
    const newId = id + '-copy-' + Date.now().toString(36);
    if (mainDir) {
      const targetFile = findEngineFile(mainDir, id);
      if (targetFile && node_fs_engine.existsSync(targetFile)) {
        const order = getNextOrder(mainDir);
        const existingContent = node_fs_engine.readFileSync(targetFile, 'utf8');
        let cloned = existingContent.replace(new RegExp('id:\\s*' + id), 'id: ' + newId);
        cloned = cloned.replace(/name:\\s*"([^"]+)"/, 'name: "$1 (Bản sao)"');
        const filename = order + '-' + newId + '.md';
        for (const d of dirs) {
          try {
            node_fs_engine.writeFileSync(node_path_engine.join(d, filename), cloned, 'utf8');
          } catch {}
        }
        await reloadBackendEngines();
        return { ok: true, code: newId };
      }
    }
    return { ok: false, error: 'SOURCE_ENGINE_NOT_FOUND' };
  } catch (err) {
    return { ok: false, error: err.message || 'CLONE_ENGINE_FAILED' };
  }
}
